// Scalability family, variant per_instance, the instantiation at S15 alone. P_k in this
// variant is the programs t0 .. t(k-1). Generated by generate.py of the scalability
// evaluation; do not edit by hand.

#[thrust_macros::context]
trait Step {
    #[thrust_macros::requires(Self::inv(x))]
    #[thrust_macros::ensures(Self::inv(result) && result > x)]
    fn step(&self, x: i64) -> i64;

    #[thrust_macros::predicate]
    fn inv(x: i64) -> bool;
}

#[derive(PartialEq)]
struct S15 {}

impl thrust_models::Model for S15 {
    type Ty = S15;
}

#[thrust_macros::context]
impl Step for S15 {
    fn step(&self, x: i64) -> i64 {
        x + 1
    }

    #[thrust_macros::predicate]
    fn inv(x: i64) -> bool {
        x >= 15
    }
}

#[thrust_macros::requires(S15::inv(x) && n >= 0)]
#[thrust_macros::ensures(S15::inv(result) && result >= x + n)]
fn repeat_s15(a: &S15, x: i64, n: i64) -> i64 {
    let mut v = x;
    let mut i = 0;
    while i < n {
        v = a.step(v);
        i += 1;
    }
    v
}

fn main() {
    let r15 = repeat_s15(&S15 {}, 14, 3);
    assert!(r15 >= 18);
}
